import{_ as o,r as e,o as i,c,e as a,a as p,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"File Settings - October CMS - 4.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Config File Structure","slug":"config-file-structure","link":"#config-file-structure","children":[]},{"level":2,"title":"Accessing Configuration Values","slug":"accessing-configuration-values","link":"#accessing-configuration-values","children":[]},{"level":2,"title":"Overriding Configuration Values","slug":"overriding-configuration-values","link":"#overriding-configuration-values","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/settings/file-settings.md","filePath":"4.x/extend/settings/file-settings.md"}'),l={name:"4.x/extend/settings/file-settings.md"};function u(g,n,d,f,m,h){const s=e("pre-heading"),t=e("post-heading");return i(),c("div",null,[a(s),n[0]||(n[0]=p("h1",null,"File Settings",-1)),a(t),n[1]||(n[1]=r(`<p>File settings keep setting values stored in files and can be overriden by the environment variables or application files.</p><h2 id="config-file-structure"><a href="#config-file-structure" class="header-anchor">#</a> Config File Structure</h2><p>Plugins can use file-based configuration files in the <strong>config</strong> subdirectory of the plugin directory. Below is an example of the plugin&#39;s <strong>config</strong> directory.</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── todo
|           └── <code>config</code>
|               ├── config.php  <em>← Configuration File</em>
|               └── custom.php  <em>← Configuration File</em></p>
</code></pre><p>The configuration files are PHP scripts that define and return an <strong>array</strong>. The following is an example configuration file <strong>config.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;display&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">5</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="accessing-configuration-values"><a href="#accessing-configuration-values" class="header-anchor">#</a> Accessing Configuration Values</h2><p>Use the <code>Config</code> facade for accessing the configuration values defined in the configuration file. The <code>get</code> method accepts the plugin and the configuration name (first argument) in the following format: <strong>acme.demo::maxItems</strong>. You may also define a default value (second argument) to return if the configuration parameter doesn&#39;t exist.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Using a different filename for the configuration file will affects the key name. For example, a configuration file named <strong>custom.php</strong> will prefix the key name with <code>custom</code>, using the following format: <strong>acme.demo::custom.maxItems</strong>. The following example is based on a configuration file named <strong>custom.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::custom.maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="overriding-configuration-values"><a href="#overriding-configuration-values" class="header-anchor">#</a> Overriding Configuration Values</h2><p>A plugin configuration file can be overridden by the application by creating a local configuration file to match, for example, to override <strong>plugins/acme/demo/config/config.php</strong>, create a file called <strong>config/acme/todo/config.php</strong>.</p><pre class="dir-container"><code><p>├── config
|   └── <code>acme</code>
|       └── <code>todo</code>
|           └── config.php  <em>← Override File</em></p>
</code></pre><p>Inside the overridden configuration file you can return only values you want to override.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">20</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>If you want to use separate configurations across different environments (eg: <strong>dev</strong>, <strong>production</strong>), consider using the <code>env()</code> helper to pull the value from an environment variable. The <code>env()</code> function accepts the environment variable name (first argument) and an optional default value if the variable doesn&#39;t exist (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ACME_TODO_MAX_ITEMS&#39;</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>This will change the <code>maxItems</code> value when the environment variable <code>ACME_TODO_MAX_ITEMS</code> is set to any other value. For example, inside the <strong>.env</strong> file for the application. See the <a href="./../../setup/configuration.html">configuration article</a> to learn how to change these values depending on the environment.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">ACME_TODO_MAX_ITEMS</span><span class="token punctuation">=</span><span class="token value attr-value">10</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../setup/configuration.html">Common Configuration</a></li></ul></div>`,22))])}const x=o(l,[["render",u]]);export{v as __pageData,x as default};
